namespace tului2 {
enum class S:uint8_t{MAIN,MCU,UTILITY,INFO,DISPLAY,NETWORK,STORAGE,ENGINEERING,ABOUT,SCAN,KEYBOARD,FORMAT,TOUCH,SD,GPIO};
static S s=S::MAIN; static bool dirty=true,down=false,shift=true,pwd=false; static String text,ssid,test; static uint8_t sig[3]={0}; static bool sigOk=false,flashOk=false;
static bool hit(uint16_t x,uint16_t y,int a,int b,int w,int h){return x>=a&&x<a+w&&y>=b&&y<b+h;} static void go(S n){s=n;dirty=true;}
template<class D>static void head(D&d,const char*t){d.fillScreen(TFT_BLACK);d.setTextSize(2);d.setTextColor(TFT_CYAN);d.setCursor(18,12);d.print(t);d.drawFastHLine(18,36,444,0x03EF);}
template<class D>static void ico(D&d,int x,int y,int n){d.setTextColor(TFT_WHITE);switch(n){case 1:d.drawRect(x-10,y-10,20,20,TFT_WHITE);d.drawRect(x-4,y-4,8,8,TFT_WHITE);break;case 2:d.drawCircle(x,y,11,TFT_WHITE);d.drawCircle(x,y,4,TFT_WHITE);break;case 3:d.drawCircle(x,y,13,TFT_WHITE);d.setCursor(x-3,y-10);d.print("i");break;case 4:d.drawRoundRect(x-15,y-10,30,20,3,TFT_WHITE);break;case 5:d.drawCircle(x-3,y-3,10,TFT_WHITE);d.drawLine(x+5,y+5,x+14,y+14,TFT_WHITE);break;case 6:d.drawRoundRect(x-13,y-15,26,30,3,TFT_WHITE);break;case 7:d.drawLine(x-12,y-12,x+12,y+12,TFT_WHITE);d.drawLine(x+12,y-12,x-12,y+12,TFT_WHITE);break;case 8:d.drawCircle(x,y-4,5,TFT_WHITE);d.drawFastVLine(x,y+1,13,TFT_WHITE);break;case 9:d.drawRect(x-12,y-10,24,20,TFT_WHITE);break;case 10:d.drawLine(x,y-15,x,y+15,TFT_WHITE);d.drawLine(x,y-15,x+9,y-6,TFT_WHITE);d.drawLine(x+9,y-6,x-7,y+8,TFT_WHITE);break;case 11:d.drawRoundRect(x-16,y-10,32,20,3,TFT_WHITE);break;case 12:d.drawLine(x+10,y,x-10,y,TFT_WHITE);d.drawLine(x-10,y,x-2,y-8,TFT_WHITE);d.drawLine(x-10,y,x-2,y+8,TFT_WHITE);break;default:break;}}
template<class D>static void btn(D&d,int x,int y,int w,int h,const char*t,uint16_t c,int i=0){d.fillRoundRect(x,y,w,h,7,c);d.drawRoundRect(x,y,w,h,7,TFT_WHITE);d.setTextColor(TFT_WHITE);d.setTextSize(2);if(i){ico(d,x+24,y+h/2,i);d.setCursor(x+45,y+(h-16)/2);}else d.setCursor(x+10,y+(h-16)/2);d.print(t);}
template<class D>static bool press(D&d,uint16_t&x,uint16_t&y){uint16_t a,b;bool q=d.getTouch(&a,&b),e=q&&!down;down=q;if(!e)return false;x=a;y=b;return true;}
template<class D>static void main(D&d){head(d,"TUL MCU FIRMWARE READER");btn(d,35,70,190,70,"MCU READER",0x03EF,1);btn(d,255,70,190,70,"UTILITY",0x801F,7);btn(d,35,165,190,70,"ENGINEERING",0xFD20,2);btn(d,255,165,190,70,"SYSTEM INFO",0x05FF,3);d.setTextColor(TFT_GREEN);d.setCursor(35,250);d.print("SD READY");}
template<class D>static void mcu(D&d){head(d,"MCU READER");d.setTextColor(TFT_WHITE);d.setTextSize(2);d.setCursor(18,55);d.print("Target: ATmega328P (manual)");d.setCursor(18,82);d.print("No automatic CPU scan at boot");d.setTextColor(sigOk?TFT_GREEN:TFT_YELLOW);d.setCursor(18,109);d.printf("Signature: %02X %02X %02X",sig[0],sig[1],sig[2]);btn(d,18,140,205,55,"READ SIGNATURE",0x03EF,5);btn(d,235,140,205,55,"READ FLASH -> SD",0x07E0,6);d.setTextColor(flashOk?TFT_GREEN:TFT_WHITE);d.setCursor(18,215);d.print(flashOk?"FLASH SAVED":"READY");btn(d,330,260,120,45,"BACK",0xF800,12);}
template<class D>static void utility(D&d){head(d,"TUL UTILITY");btn(d,18,55,135,48,"DISPLAY",0x801F,4);btn(d,165,55,135,48,"NETWORK",0x03EF,5);btn(d,312,55,135,48,"STORAGE",0x07E0,6);btn(d,18,120,135,48,"ABOUT TUL",0x05FF,3);btn(d,165,120,282,48,"ADVANCED TOOLS",0x4208,7);btn(d,330,260,120,45,"BACK",0xF800,12);}
template<class D>static void info(D&d){head(d,"SYSTEM INFO");d.setTextColor(TFT_WHITE);d.setTextSize(2);d.setCursor(18,52);d.print("CPU       ESP32-S3");d.setCursor(18,76);d.printf("RAM FREE  %lu KB",ESP.getFreeHeap()/1024UL);d.setCursor(18,100);d.printf("PSRAM     %lu / %lu KB",ESP.getFreePsram()/1024UL,ESP.getPsramSize()/1024UL);d.setCursor(18,124);d.printf("FLASH     %lu MB",ESP.getFlashChipSize()/(1024UL*1024UL));d.setCursor(18,148);d.printf("SD CARD   %llu MB",storageCapacityBytes()/(1024ULL*1024ULL));d.setCursor(18,172);d.printf("SD FREE   %llu MB",storageFreeBytes()/(1024ULL*1024ULL));d.setCursor(18,196);d.printf("WiFi      %.25s",networkSSID());d.setCursor(18,220);d.printf("IP        %s",networkIP());d.setCursor(18,244);d.printf("RSSI      %d dBm",networkRSSI());btn(d,330,260,120,45,"BACK",0xF800,12);}
template<class D>static void display(D&d){head(d,"DISPLAY");d.setTextColor(TFT_WHITE);d.setTextSize(2);d.setCursor(18,55);d.printf("Brightness: %u",settings().brightness);btn(d,20,82,100,42,"-",0xF800);btn(d,135,82,100,42,"+",0x07E0);btn(d,250,82,100,42,"100%",0x05FF);d.setCursor(18,145);d.printf("Screensaver: %u sec",settings().screensaverSeconds);btn(d,20,172,100,42,"1 MIN",0x2D7F);btn(d,135,172,100,42,"5 MIN",0x801F);btn(d,250,172,100,42,"OFF",0xF800);btn(d,330,260,120,45,"BACK",0xF800,12);}
template<class D>static void storage(D&d){head(d,"STORAGE");d.setTextColor(TFT_WHITE);d.setTextSize(2);d.setCursor(18,55);d.printf("Capacity: %llu MB",storageCapacityBytes()/(1024ULL*1024ULL));d.setCursor(18,79);d.printf("Free: %llu MB",storageFreeBytes()/(1024ULL*1024ULL));btn(d,18,112,200,48,"FORMAT SD",0xF800);btn(d,235,112,200,48,"REFRESH",0x07E0,6);btn(d,330,260,120,45,"BACK",0xF800,12);}
template<class D>static void network(D&d){head(d,"NETWORK");d.setTextColor(TFT_WHITE);d.setTextSize(2);d.setCursor(18,52);d.printf("WiFi: %s",settings().wifiEnabled?"ON":"OFF");d.setCursor(18,76);d.printf("SSID: %.25s",networkSSID());d.setCursor(18,100);d.printf("IP: %s",networkIP());btn(d,18,125,130,44,"WIFI",0x03EF,5);btn(d,160,125,130,44,"SCAN",0x07E0,5);btn(d,302,125,130,44,"BLE",0x801F,10);btn(d,18,185,130,44,"KEYBOARD",0xFD20,11);btn(d,160,185,130,44,"SAVED",0x05FF,6);d.setTextColor(TFT_YELLOW);d.setCursor(302,200);d.print(settings().bleEnabled?"ON":"OFF");btn(d,330,260,120,45,"BACK",0xF800,12);}
template<class D>static void engineering(D&d){head(d,"ENGINEERING MODE");d.setTextColor(TFT_WHITE);d.setTextSize(2);d.setCursor(18,55);d.printf("RAM %lu KB free",ESP.getFreeHeap()/1024UL);d.setCursor(18,79);d.printf("PSRAM %lu KB free",ESP.getFreePsram()/1024UL);d.setCursor(18,103);d.printf("SD %s",storageCapacityBytes()?"READY":"FAIL");btn(d,18,185,130,44,"TOUCH",0x801F,8);btn(d,160,185,130,44,"SD TEST",0x07E0,6);btn(d,302,185,130,44,"GPIO",0x03EF,9);btn(d,330,260,120,45,"BACK",0xF800,12);}
template<class D>static void test(D&d,const char*t){head(d,t);d.setTextColor(TFT_WHITE);d.setTextSize(2);d.setCursor(18,60);d.print(test.length()?test:"READY");if(s==S::TOUCH){d.drawRect(18,100,420,110,TFT_CYAN);d.setCursor(30,120);d.print("Touch inside this box");}btn(d,330,260,120,45,"BACK",0xF800,12);}
template<class D>static void scan(D&d){head(d,"WIFI SCAN");int n=networkScanCount();d.setTextColor(n==NETWORK_SCAN_RUNNING?TFT_YELLOW:TFT_WHITE);d.setCursor(18,52);if(n==NETWORK_SCAN_RUNNING)d.print("SCANNING...");else d.printf("Found: %d",n<0?0:n);if(n>0)for(int i=0;i<n&&i<7;i++){d.setCursor(18,78+i*25);d.printf("%d %-21s %d",i+1,networkScanName(i).c_str(),networkScanRSSI(i));}btn(d,330,260,120,45,"BACK",0xF800,12);}
template<class D>static void about(D&d){head(d,"ABOUT TUL");d.setTextColor(TFT_WHITE);d.setTextSize(2);d.setCursor(18,65);d.print("TUL MCU Firmware Reader");d.setCursor(18,95);d.print("Standalone Service Instrument");btn(d,330,260,120,45,"BACK",0xF800,12);}
template<class D>static void format(D&d){head(d,"FORMAT SD");d.setTextColor(TFT_RED);d.setCursor(25,65);d.print("ALL DATA WILL BE ERASED");btn(d,25,140,190,55,"CANCEL",0xFD20);btn(d,245,140,190,55,"FORMAT",0xF800);}
template<class D>static void keyboard(D&d){head(d,pwd?"WIFI PASSWORD":"WIFI SSID");d.setTextColor(TFT_WHITE);d.setTextSize(2);d.setCursor(12,42);if(pwd)for(size_t i=0;i<text.length();i++)d.print('*');else d.print(text);const char*lo="qwertyuiopasdfghjklzxcvbnm";const char*up="QWERTYUIOPASDFGHJKLZXCVBNM";for(int i=0;i<26;i++){int r=i/10,c=i%10,x=8+c*46,y=70+r*38;d.fillRoundRect(x,y,40,32,5,(i&1)?0x2D7F:0x801F);d.setCursor(x+13,y+8);d.print(shift?up[i]:lo[i]);}for(int i=0;i<10;i++){int x=8+i*46;d.fillRoundRect(x,188,40,32,5,0x2945);d.setCursor(x+13,196);d.print(i==9?'0':char('1'+i));}btn(d,8,230,62,40,"ESC",0xF800);btn(d,76,230,64,40,"SHIFT",0xFFE0);btn(d,146,230,130,40,"SPACE",0x2945);btn(d,282,230,46,40,".",0x4208);btn(d,334,230,54,40,"BKSP",0xF800);btn(d,394,230,78,40,"ENTER",0x07E0);}
template<class D>static void draw(D&d){switch(s){case S::MAIN:main(d);break;case S::MCU:mcu(d);break;case S::UTILITY:utility(d);break;case S::INFO:info(d);break;case S::DISPLAY:display(d);break;case S::NETWORK:network(d);break;case S::STORAGE:storage(d);break;case S::ENGINEERING:engineering(d);break;case S::ABOUT:about(d);break;case S::SCAN:scan(d);break;case S::KEYBOARD:keyboard(d);break;case S::FORMAT:format(d);break;case S::TOUCH:test(d,"TOUCH TEST");break;case S::SD:test(d,"SD CARD TEST");break;case S::GPIO:test(d,"GPIO TEST");break;}dirty=false;}
static void startKey(bool p,const String&i=String()){pwd=p;shift=true;text=i;text.reserve(64);go(S::KEYBOARD);}
template<class D>static void key(D&,uint16_t x,uint16_t y){if(y>=70&&y<184){int i=((y-70)/38)*10+x/46;if(i<26&&text.length()<63)text+=shift?"QWERTYUIOPASDFGHJKLZXCVBNM"[i]:"qwertyuiopasdfghjklzxcvbnm"[i];}else if(y>=188&&y<222){int n=x/46;if(text.length()<63)text+=n==9?'0':char('1'+n);}else if(y>=230){if(x<72)go(S::NETWORK);else if(x<144)shift=!shift;else if(x<280){if(text.length()<63)text+=' ';}else if(x<334){if(text.length()<63)text+='.';}else if(x<394){if(text.length())text.remove(text.length()-1);}else if(!pwd){ssid=text;startKey(true);}else{networkSaveCredentials(ssid,text);networkConnectSaved();go(S::NETWORK);}}dirty=true;}
template<class D>static void handle(D&d,uint16_t x,uint16_t y){switch(s){case S::MAIN:if(hit(x,y,35,70,190,70))go(S::MCU);else if(hit(x,y,255,70,190,70))go(S::UTILITY);else if(hit(x,y,35,165,190,70))go(S::ENGINEERING);else if(hit(x,y,255,165,190,70))go(S::INFO);break;case S::MCU:if(hit(x,y,18,140,205,55)){Atmega328pIsp i;i.begin();sigOk=i.readSignature(sig);}else if(hit(x,y,235,140,205,55)){Atmega328pIsp i;i.begin();flashOk=i.readFlashToSd("/ATmega328P_flash.bin");}else if(hit(x,y,330,260,120,45))go(S::MAIN);break;case S::UTILITY:if(hit(x,y,18,55,135,48))go(S::DISPLAY);else if(hit(x,y,165,55,135,48))go(S::NETWORK);else if(hit(x,y,312,55,135,48))go(S::STORAGE);else if(hit(x,y,18,120,135,48))go(S::ABOUT);else if(hit(x,y,165,120,282,48))go(S::ENGINEERING);else if(hit(x,y,330,260,120,45))go(S::MAIN);break;case S::INFO:if(hit(x,y,330,260,120,45))go(S::MAIN);break;case S::DISPLAY:if(hit(x,y,330,260,120,45))go(S::UTILITY);break;case S::STORAGE:if(hit(x,y,18,112,200,48))go(S::FORMAT);else if(hit(x,y,330,260,120,45))go(S::UTILITY);break;case S::FORMAT:if(hit(x,y,25,140,190,55))go(S::STORAGE);else if(hit(x,y,245,140,190,55)){storageFormat();go(S::STORAGE);}break;case S::NETWORK:if(hit(x,y,18,125,130,44))networkToggleWiFi();else if(hit(x,y,160,125,130,44)){go(S::SCAN);networkScanWiFi();}else if(hit(x,y,302,125,130,44))networkToggleBLE();else if(hit(x,y,18,185,130,44))startKey(false);else if(hit(x,y,330,260,120,45))go(S::UTILITY);break;case S::SCAN:if(hit(x,y,330,260,120,45))go(S::NETWORK);else{int n=networkScanCount();for(int i=0;i<n&&i<7;i++)if(hit(x,y,10,70+i*25,450,25)){ssid=networkScanName(i);startKey(true);break;}}break;case S::ENGINEERING:if(hit(x,y,18,185,130,44)){test="Touch test ACTIVE";go(S::TOUCH);}else if(hit(x,y,160,185,130,44)){test=storageCapacityBytes()?"SD TEST: CARD READY":"SD TEST: NO CARD";go(S::SD);}else if(hit(x,y,302,185,130,44))go(S::GPIO);else if(hit(x,y,330,260,120,45))go(S::MAIN);break;case S::TOUCH:if(hit(x,y,330,260,120,45))go(S::ENGINEERING);break;case S::SD:if(hit(x,y,330,260,120,45))go(S::ENGINEERING);break;case S::GPIO:if(hit(x,y,330,260,120,45))go(S::ENGINEERING);break;case S::ABOUT:if(hit(x,y,330,260,120,45))go(S::UTILITY);break;case S::KEYBOARD:key(d,x,y);break;}}
template<class D>void mainMenu(D&d){s=S::MAIN;down=false;dirty=true;draw(d);}template<class D>void uiLoop(D&d){if(dirty)draw(d);uint16_t x=0,y=0;if(press(d,x,y))handle(d,x,y);if(s==S::SCAN&&networkScanCount()==NETWORK_SCAN_RUNNING){static uint32_t t=0;if(millis()-t>250){t=millis();dirty=true;}}}
}
